def majorityElementII(nums):
    c1 = c2 = None
    n1 = n2 = 0
    for x in nums:
        if x == c1:
            n1 += 1
        elif x == c2:
            n2 += 1
        elif n1 == 0:
            c1, n1 = x, 1
        elif n2 == 0:
            c2, n2 = x, 1
        else:
            n1 -= 1
            n2 -= 1
    n = len(nums)
    res = []
    for c in (c1, c2):
        if c is not None and 3 * nums.count(c) > n:
            res.append(c)
    return sorted(res)
